import{z as o,x as B,o as l,c as d,q as n,j as t,D as E,d as A,s,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const b=JSON.parse('{"title":"人工评测 vs 自动评测","description":"","frontmatter":{"title":"人工评测 vs 自动评测","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/human-vs-auto-eval.md","filePath":"llm/human-vs-auto-eval.md","lastUpdated":1791413859000}'),h={name:"llm/human-vs-auto-eval.md"};function p(m,a,u,f,c,C){const r=B("Mermaid");return l(),d("div",null,[a[2]||(a[2]=n('<h1 id="人工评测-vs-自动评测" tabindex="-1">人工评测 vs 自动评测 <a class="header-anchor" href="#人工评测-vs-自动评测" aria-label="Permalink to &quot;人工评测 vs 自动评测&quot;">​</a></h1><div class="epigraph"><p>自动基准给可比的标量；人给的是任务是否被完成的判断。两者测的不是同一个随机变量，不能用其中一个去「校准」另一个却不声明条件。</p><footer>—— 对照 MMLU 一类静态卷面与 LMSYS Arena 的成对偏好</footer></div><p><a href="/llm/lmsys-arena">上一课</a> 把 Arena 写成滑动的人类偏好 Elo。本课把镜头拉宽：何时必须用人，何时自动指标足够，以及用 LLM 当法官时你实际站在哪一边。缺口不是再讲 Bradley-Terry，而是 <strong>评测设计里的角色分工</strong>。后课智能体协议与种子方差都假定：你已经为每个声明选对了人 / 自动 / 混合，而不是默认「有分就算评过」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自动评测：固定题面、程序或标准答案、可回归。适合 <a href="/llm/mmlu">MMLU</a>、<a href="/llm/math-bench">数学卷</a>、<a href="/llm/code-bench">代码单测</a>、<a href="/llm/niah">针测</a>、<a href="/llm/ifeval">IFEval</a>——即输出空间能被规则或测试吃掉的任务。人工评测：开放生成、多约束取舍、安全、产品口味。Arena 是人工的一种廉价众包形态；实验室 rubric 是另一种，更慢更可控。</p><p>错误发生在用自动分代替人去做开放任务（BLEU 式、或 LLM-as-judge 未经人校准），或用人去代替本可以单测的代码（贵、不可复现）。LLM 法官看起来自动、便宜，统计性质却像「一个未校准的标注员」：有位置偏见、长度偏见、自偏好。它既不是 Arena 的人，也不是 MATH 的校验器。<span class="marginnote">术语翻译：「LLM 法官」就是拿一个模型去给另一个模型的输出打分或比高低，用模型代替人类标注员。它便宜到能全量跑，但它自己也会犯错：把两个答案换个先后顺序，判罚就可能翻转（位置偏见）；谁写得长就更可能被判好（长度偏见）。</span></p><h3 id="声明决定仪器" tabindex="-1">声明决定仪器 <a class="header-anchor" href="#声明决定仪器" aria-label="Permalink to &quot;声明决定仪器&quot;">​</a></h3><p>「数学能力涨了」应用可验证自动集，固定预算。<a href="/llm/verifiable-reward">可验证奖励</a> 课的 \\(R\\) 甚至可以直接当评测。 「更好用」应用盲成对人评或产品 A/B。 「遵循指令」可先 IFEval 再对人抽查失败模式。一张表里混三种声明却只放 Arena 分，是仪器用错。<span class="marginnote">人评的方差来自题目抽样与评分员；自动评的方差来自解码种子与题面。后课专门拆种子。本课只要记住：人评的置信区间通常更宽，小样本名次无意义——Arena 课已强调对战次数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="先写声明再选仪器" tabindex="-1">先写声明再选仪器 <a class="header-anchor" href="#先写声明再选仪器" aria-label="Permalink to &quot;先写声明再选仪器&quot;">​</a></h3><p>设计步骤：写出产品声明 → 选主仪器（自动 / 人 / 法官）→ 选防偏（盲、长度控制、题面冻结）→ 规定复测频率。自动集要版本化，防污染。人评要写 rubric：相关性、事实、危害、格式，分项打分比单一「更好」更可诊断，但更贵。成对比较降低校准负担，适合口味；绝对 Likert 适合追趋势，但漂移大。</p><p>LLM-as-judge：必须在同一批题目上用人评校准（相关、成对一致率），并报告位置交换实验。未校准的法官只能当开发期烟雾，不能当论文主表。法官模型若与被评模型同族，自偏好要当成一等系统误差。</p>',12)),(l(),t(i,null,{default:E(()=>[s(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CLAIM%5B%22%E4%BA%A7%E5%93%81%E6%88%96%E8%AE%BA%E6%96%87%E5%A3%B0%E6%98%8E%22%5D%20--%3E%20PICK%5B%22%E9%80%89%E6%8B%A9%E4%BB%AA%E5%99%A8%22%5D%0A%20%20PICK%20--%3E%20AUTO%5B%22%E7%A8%8B%E5%BA%8F%E5%8F%AF%E5%88%A4%E5%AE%9A%EF%BC%9A%E8%87%AA%E5%8A%A8%E9%9B%86%22%5D%0A%20%20PICK%20--%3E%20HUM%5B%22%E5%BC%80%E6%94%BE%20%2F%20%E5%8F%A3%E5%91%B3%EF%BC%9A%E7%9B%B2%E4%BA%BA%E8%AF%84%22%5D%0A%20%20PICK%20--%3E%20J%5B%22%E5%BC%80%E5%8F%91%E6%9C%9F%EF%BC%9A%E6%A0%A1%E5%87%86%E8%BF%87%E7%9A%84%20LLM%20%E6%B3%95%E5%AE%98%22%5D%0A%20%20J%20--%3E%20HUM%0A%20%20AUTO%20--%3E%20REG%5B%22%E5%8F%AF%E5%9B%9E%E5%BD%92%E3%80%81%E5%8F%AF%E6%B1%A1%E6%9F%93%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[A("自动指标优化会进入训练环（RL 对校验器黑客、对 MMLU 的污染）。它测的是「对这个仪器好不好」，仪器一旦可被梯度碰到就贬值。人评更难直接进梯度（贵、慢），因此更抗投机，但样本少、题分布随招募漂。Arena 课已经写了自愿者偏技术英语。实验室人评可以分层抽样，代价是不规模。"),e("span",{class:"marginnote"},"直觉类比：这就是「刷真题」现象。学生把历年考卷背得滚瓜烂熟，卷面分上去了，真实能力没涨——因为出题套路本身成了被优化的目标。评测集一旦被模型「看见」并参与训练，它测的就不再是能力，而是背题水平，这就是文中说的「贬值」。")],-1)),a[5]||(a[5]=e("p",null,"混合协议：自动做全量筛，人做分层抽查。智能体轨迹尤其需要——全自动单测覆盖不到的「是否在胡用工具」，要人看录像或日志。这是下一课协议要标准化的对象。",-1)),(l(),t(i,null,{default:E(()=>[s(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20ALL%5B%22%E5%85%A8%E9%83%A8%E4%BA%A7%E5%87%BA%22%5D%20--%3E%20AUTO%5B%22%E8%87%AA%E5%8A%A8%E9%9B%86%E5%85%A8%E9%87%8F%E7%AD%9B%22%5D%0A%20%20AUTO%20--%3E%20DIS%5B%22%E5%88%86%E6%AD%A7%E5%8C%BA%EF%BC%9A%E8%87%AA%E5%8A%A8%E4%B8%8E%E4%BA%BA%E5%8F%AF%E8%83%BD%E4%B8%8D%E5%90%8C%22%5D%0A%20%20AUTO%20--%3E%20AGREE%5B%22%E4%B8%80%E8%87%B4%E5%8C%BA%EF%BC%9A%E7%9B%B4%E6%8E%A5%E6%94%BE%E8%A1%8C%22%5D%0A%20%20DIS%20--%3E%20STRA%5B%22%E6%8C%89%E7%B1%BB%E5%88%AB%E5%88%86%E5%B1%82%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20STRA%20--%3E%20HUM%5B%22%E4%BA%BA%E5%B7%A5%E7%9C%8B%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20HUM%20--%3E%20ACT%5B%22%E4%BF%AE%E8%AF%84%E6%B5%8B%E6%88%96%E4%BF%AE%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20ACT%20--%3E%20AUTO%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">不要用人去给 GSM8K 再打一遍分，除非在研究抽取器错误。人的时间应花在自动指标说「过了」但产品仍失败的区域，或自动指标说「挂了」但其实用户可接受的区域。差异集比再跑一张总分更有信息。</span></p><h3 id="长度与风格混淆" tabindex="-1">长度与风格混淆 <a class="header-anchor" href="#长度与风格混淆" aria-label="Permalink to &quot;长度与风格混淆&quot;">​</a></h3><p>自动长度无关的准确率仍可能与风格相关（格式分）。人评强烈爱长、爱列表。长度控制（截断再评、或强制短答）应同时出现在人评与 Arena。否则「人工评测显示更好」只是更长。这与推理 RL 长度预算是同一混淆在评测侧的镜像。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>安全评测不能只靠自动拒答率：过拒与漏拒都要人看上下文。代码可以几乎全自动，但「是否解决用户意图」仍要人。多语言人评招募比英语贵一个数量级，自动翻译再评会引入翻译模型偏见。声明若含中文产品，人评必须含中文标注员，不能用英文 Arena 代理。</p><p>成本上：自动评应每次提交都跑；人评按里程碑。把人评当 CI 会破产或导致评分员疲劳，分数漂得比模型还快。疲劳是人评特有的失效模式，协议里要有休息、金标题、淘汰不一致评分员。<span class="marginnote">数字实例：假设一次人评要看 2000 条输出，每条 3 分钟，就是 100 个工时；若做全部发布，一周迭代三次根本扛不住。改成混合协议——自动跑满 2000 条、人只抽查其中 5%（100 条）——就只要 5 个工时，且专门看自动指标最容易误判的区域，钱花在刀刃上。</span></p><p><span class="marginnote">本课不设立「人永远更正确」。人会系统性偏好谄媚与冗长。对事实任务，校准良好的自动集优于未训练的众包。仪器服从声明，不服从道德口号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>自动评测服务可判定声明；人评服务开放与口味；LLM 法官必须经人校准。</li><li>先写声明再选仪器；禁止用 Arena 代理数学能力。</li><li>人的时间花在自动与产品的差异集上。</li><li>长度偏见在人评与 Arena 上都要控制。</li><li>人评有疲劳与抽样偏；自动评有污染与投机。</li><li>出处：静态基准传统；Chatbot Arena；LLM-as-judge 的校准文献。</li></ul>',9))])}const F=o(h,[["render",p]]);export{b as __pageData,F as default};
